import { chromium } from "<project>/flare/node_modules/playwright-core/index.mjs";
export async function phone(desktop=false){
  const browser = await chromium.launch({ channel: "chrome" });
  const ctx = await browser.newContext(desktop?{viewport:{width:1280,height:800}}:{viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:2,geolocation:{latitude:42.3196,longitude:-83.2129},permissions:["geolocation"]});
  if(desktop){await ctx.grantPermissions(["geolocation"]);await ctx.setGeolocation({latitude:42.3196,longitude:-83.2129});}
  const page = await ctx.newPage();
  page.on("console",m=>{if(m.type()==="error")console.log("CONSOLE ERR:",m.text())});
  page.on("pageerror",e=>console.log("PAGEERR:",e.message));
  return {browser,ctx,page};
}
export const D="<tmp>/904c52d9-f200-4552-8ce5-05e400952efa/scratchpad/fresh/";
EOF
cat > s1.mjs <<'EOF'
import {phone,D} from "./lib.mjs";
const {browser,page}=await phone();
const t=Date.now();
await page.goto("https://flare-outside.onrender.com/",{timeout:120000});
console.log("loaded",Date.now()-t);
await page.screenshot({path:D+"01-land.png"});
await page.waitForTimeout(4000);
await page.screenshot({path:D+"01b-land5s.png"});
await page.screenshot({path:D+"01c-full.png",fullPage:true});
console.log(await page.title());
console.log((await page.innerText("body")).slice(0,4000));
const links=await page.$$eval("a,button",els=>els.map(e=>e.tagName+"|"+e.innerText.trim().slice(0,50)+"|"+(e.getAttribute("href")||"")));
console.log(links.join("\n"));
await browser.close();
EOF
node s1.mjs

