input.command:
cd <tmp>/904c52d9-f200-4552-8ce5-05e400952efa/scratchpad/fresh && cat > run.mjs <<'EOF'
// usage: node run.mjs url prefix '[["click","text=Foo"],["wait",2000],["shot"],["fill","sel","Test"]]' [d]
import {phone,D} from "./lib.mjs";
const [url,pre,acts,dd]=process.argv.slice(2);
const {browser,page}=await phone(dd==="d");
const t=Date.now();
await page.goto(url,{timeout:120000});
await page.waitForTimeout(2500);
let n=0;
async function dump(){
  const shot=`${D}${pre}-${String(n++).padStart(2,"0")}.png`;
  await page.screenshot({path:shot});
  const info=await page.evaluate(()=>{
    const vis=e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0&&getComputedStyle(e).visibility!=="hidden"};
    const els=[...document.querySelectorAll("a,button,input,select,textarea,[role=button]")].filter(vis).map(e=>`${e.tagName}${e.type?"["+e.type+"]":""}|${(e.innerText||e.value||e.getAttribute("aria-label")||e.placeholder||"").trim().replace(/\s+/g," ").slice(0,60)}|${e.getAttribute("aria-label")||""}`);
    return {url:location.href,text:document.body.innerText.replace(/\n+/g," / ").slice(0,1500),els};
  });
  console.log("=== "+shot+" t="+(Date.now()-t)+"ms\nURL "+info.url+"\nTEXT "+info.text+"\nELS\n"+info.els.join("\n"));
}
for(const a of JSON.parse(acts||"[]")){
  try{
  if(a[0]==="click") await page.locator(a[1]).first().click({timeout:a[2]||10000});
  else if(a[0]==="tap") await page.locator(a[1]).first().tap({timeout:10000});
  else if(a[0]==="fill") await page.locator(a[1]).first().fill(a[2]);
  else if(a[0]==="wait") await page.waitForTimeout(a[1]);
  else if(a[0]==="waitfor") await page.locator(a[1]).first().waitFor({timeout:a[2]||90000});
  else if(a[0]==="shot") await dump();
  else if(a[0]==="scroll") await page.mouse.wheel(0,a[1]);
  else if(a[0]==="key") await page.keyboard.press(a[1]);
  else if(a[0]==="goto") await page.goto(a[1]);
  else if(a[0]==="eval") console.log("EVAL",JSON.stringify(await page.evaluate(a[1])));
  }catch(e){console.log("ACTION FAIL",JSON.stringify(a),e.message.split("\n")[0]);await dump();}
}
await browser.close();
EOF
node run.mjs https://flare-outside.onrender.com/app/demo/ demo '[["shot"],["wait",4000],["shot"]]'

